fn contains(list: &Vec<i32>, element: i32) -> bool {
    for &item in list.iter() {
        if item == element {
            return true;
        }
    }
    false
}

fn has_common_element(list1: &Vec<i32>, list2: &Vec<i32>) -> bool {
    // To slightly optimize, iterate over the shorter list in the outer loop
    // so that we do fewer outer iterations.
    if list1.len() <= list2.len() {
        for &item in list1.iter() {
            if contains(list2, item) {
                return true;
            }
        }
    } else {
        for &item in list2.iter() {
            if contains(list1, item) {
                return true;
            }
        }
    }
    false
}

